import { Activity, AlertTriangle, Check, ChevronRight, CircleHelp, Cpu, Network, Shield, ShieldCheck, SquareTerminal } from 'lucide-vue-next'

const emit = defineEmits(['notify'])
const statusFilters = ['全部', '运行中', '已挂起', '待回收']
const sandboxes = [
