  { id: 'sbx_913c', title: '合同条款摘要', agent: '摘要整理助手 v4', elapsed: '56 秒', status: '运行中', violations: 0, level: 4, platform: 'macos', workspace: '/srv/contracts', cpu: '1 核', memory: '2 GB', pids: 64, network: '禁止外网', credentials: '短期令牌 · 1 个变量', approvals: '只读 · 自动允许' },
