  { id: 'sbx_024e', title: '订单表清洗 · 批次 0912', agent: '数据整理助手 v1', elapsed: '22 分钟', status: '已挂起', violations: 0, level: 3, platform: 'windows', workspace: 'D:/work/batch', cpu: '2 核', memory: '2 GB', pids: 128, network: '禁止外网', credentials: '短期令牌 · 1 个变量', approvals: '只读 · 自动允许' },
  { id: 'sbx_c080', title: '长文档翻译 · 第 3 批', agent: '翻译助手 v2', elapsed: '2 小时 14 分钟', status: '孤立实例', violations: 2, level: 4, platform: 'linux', workspace: '/srv/translate', cpu: '2 核', memory: '3 GB', pids: 128, network: '白名单 · 1 个域名 · 443 端口', credentials: '已过期', approvals: '待清理' },
  { id: 'sbx_65a1', title: '依赖安装验证', agent: '代码开发助手 v3', elapsed: '—', status: '已销毁', violations: 0, level: 5, platform: 'linux', workspace: '/tmp/deps', cpu: '1 核', memory: '1 GB', pids: 32, network: '已释放', credentials: '已销毁', approvals: '已完成' },
]
const levels = [
  { id: 1, name: '无隔离', method: '早期演示版本', boot: '—', cover: [0, 0, 0, 0, 0], scene: '仅供演示' },
  { id: 2, name: '进程级', method: '子进程 + 资源限制', boot: '8 毫秒', cover: [0, 0, 1, 0, 0], scene: '限制异常循环' },
