  { id: 5, name: '容器', method: 'Docker、Podman', boot: '1.4 秒', cover: [1, 1, 1, 1, 1], scene: '运行来源不明的依赖' },
  { id: 6, name: '微型虚拟机', method: 'Firecracker、Cloud Hypervisor', boot: '180 毫秒', cover: [1, 1, 1, 1, 1], scene: '执行外部代码' },
  { id: 7, name: '完整虚拟机', method: 'KVM、VirtualBox', boot: '6.5 秒', cover: [1, 1, 1, 1, 1], scene: '多租户强隔离' },
  { id: 8, name: '远程沙箱', method: '托管执行节点', boot: '2.2 秒', cover: [1, 1, 1, 1, 1], scene: '本机没有容器运行环境' },
]
const topics = ['隔离层级', '文件系统', '网络', '进程资源', '凭据隔离', '权限审批', '生命周期', '完整性加固', '编排策略', '可观测审计', '成熟度']
const topicContent = [
  ['八档隔离层级', '强度递增 · 启动开销同步上升', '平台决定可用层级。同一条策略在不同平台走不同实现，跨平台 Harness 应把策略语义与实现分开。'],
  ['文件系统边界', '工作区挂载与写入范围', '默认只读挂载；只开放任务需要的目录。敏感目录、密钥目录和宿主系统路径始终排除。'],
  ['网络出口', '默认拒绝 · 按域名与端口放行', '网络白名单绑定任务用途，并记录每次连接尝试；禁止通过 DNS 或代理绕过策略。'],
  ['进程与资源', '进程数、处理器、内存和运行时限额', '资源限制在运行启动时生效。达到上限时终止运行并记录触发维度和采样数据。'],
  ['凭据隔离', '由凭据服务按需签发短期凭据', '凭据只通过受控通道注入，不进入命令行参数、环境转储或普通日志。'],
  ['权限与审批', '按操作风险设置确认策略', '文件写入、外部网络和高影响工具调用分别设置审批要求；超时默认拒绝。'],
  ['隔离环境生命周期', '创建、挂起、恢复、销毁与回收', '运行结束后回收命名空间、临时文件和短期凭据；无主实例进入限时清理队列。'],
  ['完整性加固', '基线、只读挂载与策略校验', '启动前校验镜像、配置与挂载清单；运行期间检测策略漂移并留下证据。'],
  ['编排策略', '策略表达与平台实现分层', '一个策略可以映射到 Linux、macOS、Windows 或远程执行器，平台能力不足时明确报告降级。'],
  ['可观测与审计', '拦截事件、越界尝试和策略变更', '事件包含沙箱 ID、运行 ID、策略版本和结果，不记录凭据值或不必要的文件内容。'],
  ['成熟度评估', '以覆盖证据验证隔离质量', '检查能力覆盖、平台适配、降级行为、审计完整度与回收测试。'],
]
const platformOptions = [
  { id: 'linux', label: 'Linux', implementation: 'bubblewrap + Landlock + PID namespace', maxLevel: 6 },
  { id: 'macos', label: 'macOS', implementation: 'Seatbelt profile', maxLevel: 6 },
  { id: 'windows', label: 'Windows', implementation: '受限令牌 + 提权后端', maxLevel: 5 },
]
const filter = ref('全部')
const search = ref('')
const selectedId = ref('sbx_7f3a')
const selectedLevel = ref(4)
const platform = ref('linux')
const activeTopic = ref(0)
const activeSandbox = computed(() => sandboxes.find(item => item.id === selectedId.value) || sandboxes[0])
const activePlatform = computed(() => platformOptions.find(item => item.id === platform.value) || platformOptions[0])
const activeLevel = computed(() => levels.find(item => item.id === selectedLevel.value) || levels[3])
const filteredSandboxes = computed(() => sandboxes.filter(item => {
  const statusMatch = filter.value === '全部' || (filter.value === '待回收' ? ['孤儿', '已销毁'].includes(item.status) : item.status === filter.value)
  return statusMatch && `${item.title} ${item.agent} ${item.id}`.toLowerCase().includes(search.value.toLowerCase())
}))
watch(filteredSandboxes, rows => {
  if (rows.length && !rows.some(item => item.id === selectedId.value)) selectSandbox(rows[0])
})
const topic = computed(() => topicContent[activeTopic.value])
const supportLabel = computed(() => selectedLevel.value > activePlatform.value.maxLevel ? '不支持' : '可用')
const layerMatrix = [
  ['无隔离', '✕ 无', '✕ 无', '✕ 无', '✕ 无', '✕', '—', '仅 demo'],
  ['进程级', '✕ 无', '✕ 无', '~ 弱', '✕ 无', '✕', '8ms', '只防死循环'],
  ['系统调用过滤', '~ 弱', '~ 弱', '✕ 无', '~ 部分', '✕', '24ms', '只读工具'],
  ['命名空间', '✓ 强', '✓ 强', '✓ 强', '✓ 强', 'cgroup', '120ms', '默认推荐'],
  ['容器', '✓ 强', '✓ 强', '✓ 强', '✓ 强', 'cgroup', '1400ms', '不可信依赖'],
  ['微虚拟机', '✓ 强', '✓ 强', '✓ 强', '✓ 强', 'cgroup', '180ms', '执行外部代码'],
  ['完整 VM', '✓ 强', '✓ 强', '✓ 强', '✓ 强', 'cgroup', '6500ms', '多租户强隔离'],
  ['远程沙箱', '✓ 强', '✓ 强', '✓ 强', '✓ 强', 'cgroup', '2200ms', '本地无容器运行时'],
]
function selectSandbox(item) { selectedId.value = item.id; selectedLevel.value = item.level; platform.value = item.platform }
function chooseLevel(level) {
  selectedLevel.value = level.id
  if (level.id > activePlatform.value.maxLevel) emit('notify', `${activePlatform.value.label}不支持${level.name}档，策略标记为不支持`)
}
</script>

<template>
  <section class="isolation-console" aria-label="执行隔离控制台">
    <header class="isolation-head"><div class="isolation-brand"><span><Shield :size="17" /></span><div><h1>执行隔离</h1><small>隔离层级 / 文件 / 网络 / 进程 / 凭据 / 审批 / 生命周期</small></div></div><p>隔离不是一个开关，而是五个维度共同作用</p></header>
    <div class="isolation-grid">
      <aside class="sandbox-catalog">
        <nav class="sandbox-filters" aria-label="沙箱状态筛选"><button v-for="item in statusFilters" :key="item" :class="{ active: filter === item }" @click="filter = item">{{ item }}<small>{{ item === '全部' ? 7 : item === '运行中' ? 4 : item === '已挂起' ? 1 : 2 }}</small></button></nav>
        <label class="sandbox-search"><Search :size="13" /><input v-model="search" aria-label="搜索隔离环境" placeholder="搜索运行任务或智能体" /></label>
        <div class="sandbox-list"><button v-for="item in filteredSandboxes" :key="item.id" class="sandbox-row" :class="{ selected: selectedId === item.id }" @click="selectSandbox(item)"><i :class="['运行中'].includes(item.status) ? 'live' : item.status === '已挂起' ? 'paused' : item.status === '孤儿' ? 'orphan' : 'destroyed'"></i><span><strong>{{ item.title }}</strong><small>{{ item.agent }} <em>{{ item.status }}</em><b v-if="item.violations">越界 {{ item.violations }}</b></small></span><code>{{ item.elapsed }}</code></button><p v-if="!filteredSandboxes.length" class="sandbox-empty">没有匹配的沙箱</p></div>
        <footer class="sandbox-footer">共 7 个沙箱 <span>运行中 <b>4</b></span><small><i class="live"></i>运行　<i class="paused"></i>挂起　<i class="orphan"></i>孤儿　<i class="destroyed"></i>已销毁</small></footer>
      </aside>

      <main class="isolation-main">
        <nav class="isolation-tabs" aria-label="隔离策略主题"><button v-for="(item, index) in topics" :key="item" :class="{ active: activeTopic === index }" @click="activeTopic = index"><small>{{ String(index + 1).padStart(2, '0') }}</small>{{ item }}</button></nav>
        <div class="isolation-scroll">
          <template v-if="activeTopic === 0">
            <section class="tier-section"><header><h2>{{ topic[0] }} <small>{{ topic[1] }}</small></h2></header><div class="tier-list"><button v-for="level in levels" :key="level.id" class="tier-row" :class="{ chosen: selectedLevel === level.id, unsupported: level.id > activePlatform.maxLevel }" @click="chooseLevel(level)"><strong>{{ level.id }}</strong><span><b>{{ level.name }}</b><small>{{ level.method }}</small></span><code>{{ level.boot }}</code><em v-if="level.id > activePlatform.maxLevel">不支持</em><Check v-else-if="selectedLevel === level.id" :size="14" /></button></div>
              <p class="isolation-callout"><ShieldCheck :size="14" />{{ topic[2] }}</p>
